(()=>{const rows=[...document.querySelectorAll('.story')],search=document.querySelector('#search'),buttons=[...document.querySelectorAll('.filter')];let group='all';function apply(){let count=0;const q=search.value.toLowerCase().trim();for(const row of rows){row.hidden=!(group==='all'||row.dataset.group===group)||!row.textContent.toLowerCase().includes(q);if(!row.hidden)count++}document.querySelector('.count').textContent=count+' 项';document.querySelector('.empty').hidden=count!==0;buttons.forEach(b=>{b.classList.toggle('active',b.dataset.group===group);b.setAttribute('aria-pressed',String(b.dataset.group===group))})}search.addEventListener('input',apply);buttons.forEach(b=>b.addEventListener('click',()=>{group=b.dataset.group;apply()}));apply()})();
